        '운영기', DATE '2025-03-06', '인터페이스 메세지 오류로 인해 예외처리.
- MSMCSFDM 테이블 데이터가 없으면 메세지 생성 오류. (MSMCSFDM 테이블에는 PDF 3MB 이하 일 때 데이터가 들어감)
- MSMCSFDM 데이터 없으면 MSSEORUD 생성 하지 않도록 수정
운영기 문제 INF_ID ORU20250301001054617

